/**
 * Helpers for voiceovers generated by `npm run voiceover -- voiceover/<name>.json`.
 * Import the generated manifest from src/voiceover/<name>.json.
 */

export type VoiceoverLine = {
  id: string;
  text: string;
  voice: string;
  /** Path relative to public/, pass to staticFile(). */
  src: string;
  durationInSeconds: number;
  hash: string;
};

export type VoiceoverManifest = {
  name: string;
  model: string;
  totalSeconds: number;
  lines: VoiceoverLine[];
};

export type TimedVoiceoverLine = VoiceoverLine & {
  /** Start frame relative to where the voiceover begins. */
  from: number;
  durationInFrames: number;
};

/**
 * Lays lines out back to back with a pause between them. Use the returned
 * `from` / `durationInFrames` to time visuals to each spoken line.
 */
export const voiceoverTimeline = (
  manifest: VoiceoverManifest,
  fps: number,
  { gapSeconds = 0.35, startSeconds = 0 } = {},
): TimedVoiceoverLine[] => {
  let cursor = startSeconds;
  return manifest.lines.map((line) => {
    const timed = {
      ...line,
      from: Math.round(cursor * fps),
      durationInFrames: Math.ceil(line.durationInSeconds * fps),
    };
    cursor += line.durationInSeconds + gapSeconds;
    return timed;
  });
};

/** Total frames the timeline occupies (useful for durationInFrames). */
export const voiceoverDurationInFrames = (
  manifest: VoiceoverManifest,
  fps: number,
  options?: { gapSeconds?: number; startSeconds?: number },
) => {
  const timeline = voiceoverTimeline(manifest, fps, options);
  const last = timeline[timeline.length - 1];
  return last ? last.from + last.durationInFrames : 0;
};
